update answer_options set misconception_code = 'GRPH-HORIZONTAL', feedback = 'You might have thought that x = 3 is horizontal, but it is vertical — every point on it has x-value 3. y = 3 is the horizontal one.'
 where position = 2
   and question_id = (select id from questions where prompt = 'Which line is horizontal?' and origin = 'SEED');
update answer_options set misconception_code = 'GRPH-HORIZONTAL', feedback = 'You might have thought that y = 3x is horizontal, but it slopes — it passes through (0, 0) and (1, 3).'
 where position = 3
   and question_id = (select id from questions where prompt = 'Which line is horizontal?' and origin = 'SEED');
update answer_options set misconception_code = 'GRPH-HORIZONTAL', feedback = 'You might have thought that x + y = 3 is horizontal, but it slopes downwards.'
 where position = 4
   and question_id = (select id from questions where prompt = 'Which line is horizontal?' and origin = 'SEED');
update answer_options set misconception_code = 'GRPH-NOT-CHECKED', feedback = 'You might have thought that (2, 3) is on the line, but substituting x = 2 gives 2 + 2 = 4, not 3.'
 where position = 4
   and question_id = (select id from questions where prompt = 'Find every point that lies on the line y = x + 2.' and origin = 'SEED');
update answer_options set misconception_code = 'GRPH-ADD-NOT-TIMES', feedback = 'You might have thought that (3, 6) is on the line, but x is added to 2, not multiplied by it: 3 + 2 = 5.'
 where position = 5
   and question_id = (select id from questions where prompt = 'Find every point that lies on the line y = x + 2.' and origin = 'SEED');
update answer_options set misconception_code = 'GRPH-NOT-CHECKED', feedback = 'You might have thought that (0, −2) is not on the line, but substituting x = 0 gives 3 × 0 − 2 = −2, which is exactly its y.'
 where position = 2
   and question_id = (select id from questions where prompt = 'Which point is not on the line y = 3x − 2?' and origin = 'SEED');
update answer_options set misconception_code = 'GRPH-NOT-CHECKED', feedback = 'You might have thought that (1, 1) is not on the line, but substituting x = 1 gives 3 × 1 − 2 = 1, which is its y.'
 where position = 3
   and question_id = (select id from questions where prompt = 'Which point is not on the line y = 3x − 2?' and origin = 'SEED');
update answer_options set misconception_code = 'GRPH-NOT-CHECKED', feedback = 'You might have thought that (2, 4) is not on the line, but substituting x = 2 gives 3 × 2 − 2 = 4, which is its y.'
 where position = 4
   and question_id = (select id from questions where prompt = 'Which point is not on the line y = 3x − 2?' and origin = 'SEED');
update answer_options set misconception_code = 'GRPH-AXIS-CONFUSED', feedback = 'You might have thought that (0, 2) is on the x-axis, but its y-value is 2, so it is on the y-axis. On the x-axis the y-value is 0.'
 where position = 4
   and question_id = (select id from questions where prompt = 'Tick the points that lie on the x-axis.' and origin = 'SEED');
update answer_options set misconception_code = 'GRPH-AXIS-CONFUSED', feedback = 'You might have thought that (2, 3) is on an axis, but neither of its coordinates is 0. On the x-axis the y-value is 0, and on the y-axis the x-value is 0.'
 where position = 5
   and question_id = (select id from questions where prompt = 'Tick the points that lie on the x-axis.' and origin = 'SEED');
update answer_options set misconception_code = 'GRPH-M-IS-C', feedback = 'You might have thought that the equation is y = 5x − 2, but that swaps them. The gradient is −2 and it crosses at (0, 5).'
 where position = 2
   and question_id = (select id from questions where prompt = 'A line passes through (0, 5) and has gradient −2. Which is its equation?' and origin = 'SEED');
update answer_options set misconception_code = 'GRPH-CONSTANT-DROPPED', feedback = 'You might have thought that the equation is y = −2x, but that leaves out where the line crosses: it passes through (0, 5), so it is y = −2x + 5.'
 where position = 3
   and question_id = (select id from questions where prompt = 'A line passes through (0, 5) and has gradient −2. Which is its equation?' and origin = 'SEED');
update answer_options set misconception_code = 'GRPH-SIGN-DROPPED', feedback = 'You might have thought that the equation is y = 2x + 5, but the gradient is negative — the line goes down — so it is y = −2x + 5.'
 where position = 4
   and question_id = (select id from questions where prompt = 'A line passes through (0, 5) and has gradient −2. Which is its equation?' and origin = 'SEED');
update answer_options set misconception_code = 'ALG-PARTIAL-SUBSTITUTION', feedback = 'You might have thought that y = 12, but that is 4 × 3 with the −1 left out. Substituting gives 4 × 3 − 1 = 11.'
 where position = 2
   and question_id = (select id from questions where prompt = 'A line has equation y = 4x − 1. What is the value of y when x = 3?' and origin = 'SEED');
